import fitz
import json

doc = fitz.open("/root/latex_paper.pdf")

# Function to extract text blocks with spatial coordinates
def extract_equation_regions(page):
    """Extract text from specific regions"""
    blocks = page.get_text("dict")["blocks"]

    # Group text elements by approximate y-coordinate (within 5 points)
    y_groups = {}

    for block in blocks:
        if "lines" not in block:
            continue
        for line in block["lines"]:
            y = round(line["bbox"][1] / 5) * 5  # Group by 5-point intervals
            if y not in y_groups:
                y_groups[y] = []

            for span in line["spans"]:
                y_groups[y].append({
                    'text': span["text"],
                    'x': span["bbox"][0],
                    'y': span["bbox"][1],
                    'font_size': span["size"]
                })

    # For each y-group, sort by x-coordinate and combine
    combined_lines = []
    for y in sorted(y_groups.keys()):
        # Sort spans by x-coordinate
        sorted_spans = sorted(y_groups[y], key=lambda s: s['x'])
        line_text = ''.join([s['text'] for s in sorted_spans])
        combined_lines.append({
            'y': y,
            'text': line_text.strip()
        })

    return combined_lines

print("EXTRACTING FORMULAS BY SPATIAL RECONSTRUCTION")
print("="*80)

# Extract from Page 2 (equation 1)
page2 = doc[1]
lines_p2 = extract_equation_regions(page2)

print("\nPage 2 - Looking for Equation (1):")
print("-"*80)
# Find the equation region
for i, line in enumerate(lines_p2):
    if 'dt2' in line['text'] or 'd2xi' in line['text'] or '(1)' in line['text']:
        # Print surrounding context
        start = max(0, i-5)
        end = min(len(lines_p2), i+8)
        for j in range(start, end):
            if lines_p2[j]['text']:
                print(f"{lines_p2[j]['text']}")

print("\n" + "="*80)
print("\nPage 2 - Looking for Equation (2):")
print("-"*80)
for i, line in enumerate(lines_p2):
    if 'ρc(τ)' in line['text']:
        start = max(0, i-2)
        end = min(len(lines_p2), i+5)
        for j in range(start, end):
            if lines_p2[j]['text']:
                print(f"{lines_p2[j]['text']}")
        break

# Extract from Page 3
page3 = doc[2]
lines_p3 = extract_equation_regions(page3)

print("\n" + "="*80)
print("\nPage 3 - Looking for Equation (3):")
print("-"*80)
for i, line in enumerate(lines_p3):
    if 'Hi,M' in line['text'] or '(ℏ/2)' in line['text']:
        start = max(0, i-2)
        end = min(len(lines_p3), i+10)
        for j in range(start, end):
            if lines_p3[j]['text']:
